function createEvent(e,t){document.querySelector(e).dispatchEvent(new Event("eventType"))}import{myModal}from"/static/js/main.min.js";export function docSetup(){document.querySelectorAll(".modal").forEach(e=>{e.addEventListener("hide.bs.modal",()=>{document.activeElement.blur()})});let e=document.getElementById("add-workspace-modal");e.querySelector("#add-workspace-modal-save").addEventListener("click",function(){saveWorkspace(e)});const t=document.querySelectorAll('[data-bs-toggle="tooltip"]');[...t].map(e=>new bootstrap.Tooltip(e))}export async function initiateSaveWorkspaceModal(e,t){e.querySelectorAll(".error").forEach(function(e){e.setAttribute("hidden","true")})}export async function saveWorkspace(e){e.querySelectorAll(".error").forEach(function(e){e.setAttribute("hidden","true")});let t=document.getElementById("add-workspace-name"),o=t.value;if(""==o)return void e.querySelector(".ws-name-required").removeAttribute("hidden");let n=document.getElementById("add-workspace-notes").value;const r=await fetch("/add-workspace",{method:"POST",headers:{"Content-Type":"application/json; charset=utf-8"},body:JSON.stringify({workspace_name:o,workspace_notes:n})});if(!r.ok)return console.log("Response status: "+r.status),!1;const a=await r.json();if("99"==a.result){let t=e.querySelector(".error");return t.removeAttribute("hidden"),void(t.innerHTML="This workspace name has already been used.")}if(0==a.result)return void console.log("No data returned - server-side error with adding workspace.");document.getElementById("workspace-input").reset(),document.getElementById("add-workspace-modal-close").click();let s=document.querySelector("meta[name='page-identifier']").getAttribute("content");"workspaces"==s?window.location.reload():"main"==s&&myModal.show()}export async function loadData(e){const t=await fetch(e);if(!t.ok)return console.log("Route "+e+"; Response status: "+t.status),!1;const o=await t.json();return 0==o.length&&o.push(0),o}export function showSpinner(e,t){let o="";1==t&&(o="<div class='spinner-border text-primary' role='status'><span class='visually-hidden'>Loading...</span></div>"),e.querySelector(".spinner").innerHTML=o}export function insert_text(e,t){showSpinner(e,!1),e.querySelector(".content").innerText=t}export function displayMessage(e=""){if(""!=e){document.getElementById("confirmation-message").innerHTML=e;const t=new bootstrap.Modal(document.getElementById("confirmModal"));t.show()}}export function destroyModalAccordion(e){let t=e.querySelectorAll(".accordion-item");t.forEach(function(e){e.classList.contains("template-accordion")||e.remove()})}